pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint256 inputBaseAmount, uint256 inputWeightSum, uint256 royaltyFee1, uint256 royaltyFee2, bool payRoyalties) public {
        // Bound parameters to admissible ranges
        uint256 virtualBase = 100 ether;
        uint256 virtualNft = 10 ether;
        uint256 feeRate = 100; // 1%
        uint16 protocolFeeRate = 0;
        inputWeightSum = bound(inputWeightSum, 1 ether, 9 ether);
        inputBaseAmount = bound(inputBaseAmount, 1 ether, 100 ether);
        royaltyFee1 = bound(royaltyFee1, 0, 10 ether);
        royaltyFee2 = bound(royaltyFee2, 0, 10 ether);

        // Set up pool state
        vm.prank(address(this));
        c.initialize(
            address(0), // baseToken = ETH
            address(this), // nft
            uint128(virtualBase),
            uint128(virtualNft),
            0, // changeFee
            uint16(feeRate),
            bytes32(0), // merkleRoot
            false, // useStolenNftOracle
            payRoyalties
        );

        // Fund buyer
        address buyer = address(0x1234);
        vm.deal(buyer, 1000 ether);

        // Calculate expected netInputAmount before modification
        (uint256 expectedNetInput,,) = c.buyQuote(inputWeightSum);
        uint256 totalRequired = expectedNetInput;
        if (payRoyalties && (royaltyFee1 > 0 || royaltyFee2 > 0)) {
            totalRequired = expectedNetInput + royaltyFee1 + royaltyFee2;
        }

        // Perform buy with fuzz parameters; we observe the actual ETH taken by checking buyer balance before/after
        uint256 balanceBefore = buyer.balance;
        vm.prank(buyer);
        // Use try/catch to handle possible revert due to insufficient payment
        bool success;
        try c.buy{value: totalRequired}(new uint256[](2), new uint256[](2), C.MerkleMultiProof(new bytes32[](0), new bool[](0))) {
            success = true;
        } catch {
            success = false;
        }
        uint256 balanceAfter = buyer.balance;
        uint256 actualSpent = balanceBefore - balanceAfter;

        // Property: The amount spent by the buyer must be at least the base cost plus royalty fees
        // This holds for correct implementation; buggy version fails when payRoyalties is true and royalties > 0
        assertTrue(!success || actualSpent >= totalRequired);
    }
}
